"""
Builds the installer scripts the dashboard's "Add agent" wizard hands out.
The manager fills in its own address and the enrollment password, so the
person adding a machine pastes ONE command and edits nothing.
"""
import re

SH = r'''#!/bin/sh
# IDPS host agent installer for Linux and macOS. Generated by your IDPS dashboard.
set -e
MANAGER="__MANAGER__"
TOKEN="__TOKEN__"
NAME="${IDPS_AGENT_NAME:-$(hostname)}"
NAME="$(printf '%s' "$NAME" | tr -cd 'A-Za-z0-9._-')"
DIR="${IDPS_AGENT_DIR:-/opt/idps-agent}"

if [ "$(id -u)" -ne 0 ]; then echo "Please run this as root, e.g.  ... | sudo sh"; exit 1; fi
if ! command -v python3 >/dev/null 2>&1; then
  echo "Python 3 is required. On Ubuntu/Debian: apt install python3   On macOS: xcode-select --install"; exit 1
fi

echo "==> Downloading the agent from $MANAGER"
mkdir -p "$DIR"
if command -v curl >/dev/null 2>&1; then curl -fsSL "$MANAGER/agent/agent.py?token=$TOKEN" -o "$DIR/agent.py"
else wget -q "$MANAGER/agent/agent.py?token=$TOKEN" -O "$DIR/agent.py"; fi

echo "==> Looking for a web server and files to watch"
LOGS=""
for f in /var/log/nginx/access.log /var/log/apache2/access.log /var/log/httpd/access_log /var/log/httpd/access.log \
         /opt/homebrew/var/log/nginx/access.log /usr/local/var/log/nginx/access.log /usr/local/var/log/httpd/access_log; do
  [ -f "$f" ] && LOGS="$LOGS\"$f\","
done
FIM=""
for f in /etc/nginx/nginx.conf /etc/apache2/apache2.conf /etc/httpd/conf/httpd.conf /etc/ssh/sshd_config \
         /var/www/html /usr/share/nginx/html /opt/homebrew/var/www /usr/local/var/www; do
  [ -e "$f" ] && FIM="$FIM\"$f\","
done
LOGS="[${LOGS%,}]"; FIM="[${FIM%,}]"
echo "    web logs: $LOGS"
echo "    watching: $FIM"

cat > "$DIR/config.json" <<EOF
{"manager_url": "$MANAGER", "enrollment_password": "$TOKEN", "agent_name": "$NAME", "web_logs": $LOGS, "fim_paths": $FIM}
EOF
chmod 600 "$DIR/config.json"
PY="$(command -v python3)"

echo "==> Enrolling with the manager"
"$PY" "$DIR/agent.py" --config "$DIR/config.json" --enroll-only

if [ "$(uname -s)" = "Darwin" ]; then
  PLIST=/Library/LaunchDaemons/com.idps.agent.plist
  cat > "$PLIST" <<EOF
<?xml version="1.0" encoding="UTF-8"?>
<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">
<plist version="1.0"><dict>
<key>Label</key><string>com.idps.agent</string>
<key>ProgramArguments</key><array><string>$PY</string><string>$DIR/agent.py</string><string>--config</string><string>$DIR/config.json</string></array>
<key>RunAtLoad</key><true/><key>KeepAlive</key><true/>
<key>StandardOutPath</key><string>$DIR/agent.log</string><key>StandardErrorPath</key><string>$DIR/agent.log</string>
</dict></plist>
EOF
  launchctl unload "$PLIST" 2>/dev/null || true
  launchctl load -w "$PLIST"
  echo "==> Done. Running as a macOS service (com.idps.agent)."
elif [ -d /run/systemd/system ]; then
  cat > /etc/systemd/system/idps-agent.service <<EOF
[Unit]
Description=IDPS host agent
After=network-online.target
Wants=network-online.target
[Service]
ExecStart=$PY $DIR/agent.py --config $DIR/config.json
Restart=always
RestartSec=5
[Install]
WantedBy=multi-user.target
EOF
  systemctl daemon-reload
  systemctl enable --now idps-agent
  echo "==> Done. Running as a systemd service (idps-agent). Logs: journalctl -u idps-agent -f"
else
  nohup "$PY" "$DIR/agent.py" --config "$DIR/config.json" >"$DIR/agent.log" 2>&1 &
  echo "==> Done. Started in the background (no systemd found). Logs: $DIR/agent.log"
fi
echo "This machine should appear on the dashboard's Agents page within a few seconds."
'''

PS1 = r'''# IDPS host agent installer for Windows. Generated by your IDPS dashboard.
# Run this in an ADMINISTRATOR PowerShell window.
$ErrorActionPreference = "Stop"
$Manager = "__MANAGER__"
$Token = "__TOKEN__"
$Name = $env:COMPUTERNAME
$Dir = Join-Path $env:ProgramData "IDPSAgent"

$py = $null
foreach ($c in @("py", "python", "python3")) {
  $cmd = Get-Command $c -ErrorAction SilentlyContinue
  if ($cmd) { $py = $cmd.Source; break }
}
if (-not $py) {
  Write-Host "Python 3 is required. Install it with:  winget install Python.Python.3.12"
  Write-Host "Then open a NEW administrator PowerShell and run this command again."
  exit 1
}

Write-Host "==> Downloading the agent from $Manager"
New-Item -ItemType Directory -Force -Path $Dir | Out-Null
Invoke-WebRequest -UseBasicParsing -Uri "$Manager/agent/agent.py?token=$Token" -OutFile (Join-Path $Dir "agent.py")

Write-Host "==> Looking for a web server and files to watch"
$logs = @()
foreach ($p in @("C:\inetpub\logs\LogFiles\W3SVC1\*.log", "C:\nginx\logs\access.log", "C:\Apache24\logs\access.log", "C:\xampp\apache\logs\access.log")) {
  if (Test-Path $p) { $logs += $p }
}
$fim = @()
foreach ($p in @("C:\inetpub\wwwroot", "C:\Apache24\htdocs", "C:\xampp\htdocs")) {
  if (Test-Path $p) { $fim += $p }
}
$cfg = @{ manager_url = $Manager; enrollment_password = $Token; agent_name = $Name; web_logs = $logs; fim_paths = $fim }
($cfg | ConvertTo-Json -Depth 4) | Set-Content -Encoding ASCII (Join-Path $Dir "config.json")

Write-Host "==> Enrolling with the manager"
& $py (Join-Path $Dir "agent.py") --config (Join-Path $Dir "config.json") --enroll-only
if ($LASTEXITCODE -ne 0) { Write-Host "Enrollment failed. Check the manager address and that the manager is running."; exit 1 }

$pyexe = (& $py -c "import sys; print(sys.executable)").Trim()
$run = '"' + $pyexe + '" "' + (Join-Path $Dir "agent.py") + '" --config "' + (Join-Path $Dir "config.json") + '"'
schtasks /Create /TN "IDPS Agent" /TR $run /SC ONSTART /RU SYSTEM /RL HIGHEST /F | Out-Null
schtasks /Run /TN "IDPS Agent" | Out-Null
Write-Host "==> Done. This computer will appear on the dashboard's Agents page within a few seconds."
'''

_URL = re.compile(r"^https?://[A-Za-z0-9.\-\[\]:]+$")


def valid_manager(url):
    return bool(_URL.match(url or ""))


def render(kind, manager, token):
    if not valid_manager(manager):
        raise ValueError("bad manager address")
    if not re.match(r"^[A-Za-z0-9_\-]+$", token or ""):
        raise ValueError("bad token")
    tpl = SH if kind == "sh" else PS1
    return tpl.replace("__MANAGER__", manager).replace("__TOKEN__", token)


def commands(manager, token):
    return {
        "linux": 'curl -fsSL "%s/agent/install.sh?token=%s" | sudo sh' % (manager, token),
        "mac": 'curl -fsSL "%s/agent/install.sh?token=%s" | sudo sh' % (manager, token),
        "windows": "iex ((New-Object Net.WebClient).DownloadString('%s/agent/install.ps1?token=%s'))" % (manager, token),
    }
